const game = new GF.Game({
  id: 'breach-breaker',
  title: 'Breach Breaker',
  width: 960,
  height: 540,
  palette: ['#2c3e50', '#3498db', '#e67e22', '#ecf0f1'],
  background: '#2c3e50'
});

let playerUnits = [];
let enemies = [];
let gridSize = 40;
let turnCounter = 0;

function createUnit(x, y) {
  return { x, y, size: gridSize, color: game.palette[1] };
}

function createEnemy(x, y) {
  return { x, y, size: gridSize, color: game.palette[2], hp: 100 };
}

function initUnits() {
  playerUnits = [createUnit(3, 3), createUnit(5, 3)];
}

function initEnemies() {
  enemies = [createEnemy(7, 3), createEnemy(9, 3)];
}

function drawGrid(ctx) {
  ctx.strokeStyle = game.palette[3];
  ctx.lineWidth = 1;
  for (let x = 0; x < game.W; x += gridSize) {
    for (let y = 0; y < game.H; y += gridSize) {
      ctx.strokeRect(x, y, gridSize, gridSize);
    }
  }
}

function drawUnits(ctx) {
  for (const unit of playerUnits) {
    ctx.fillStyle = unit.color;
    ctx.fillRect(unit.x * gridSize, unit.y * gridSize, unit.size, unit.size);
    ctx.strokeStyle = '#ecf0f1';
    ctx.lineWidth = 2;
    ctx.strokeRect(unit.x * gridSize, unit.y * gridSize, unit.size, unit.size);
  }
}

function drawEnemies(ctx) {
  for (const enemy of enemies) {
    ctx.fillStyle = enemy.color;
    ctx.fillRect(enemy.x * gridSize, enemy.y * gridSize, enemy.size, enemy.size);
  }
}

function updateUnits(dt) {
  for (const unit of playerUnits) {
    if (game.input.pressed('ArrowRight')) unit.x = Math.min(unit.x + 1, game.W / gridSize - 1);
    if (game.input.pressed('ArrowLeft')) unit.x = Math.max(unit.x - 1, 0);
    if (game.input.pressed('ArrowDown')) unit.y = Math.min(unit.y + 1, game.H / gridSize - 1);
    if (game.input.pressed('ArrowUp')) unit.y = Math.max(unit.y - 1, 0);
  }
}

function updateEnemies(dt) {
  // Placeholder for enemy movement logic
}

function checkCollisions() {
  for (const unit of playerUnits) {
    for (const enemy of enemies) {
      if (unit.x === enemy.x && unit.y === enemy.y) {
        game.shake(5, 0.2);
        game.hitStop(0.1);
        game.burst(unit.x * gridSize + gridSize / 2, unit.y * gridSize + gridSize / 2, {
          count: 10,
          speed: 100,
          size: 5,
          life: 0.5,
          colors: [game.palette[2]],
          gravity: 50
        });
        enemy.hp -= 50;
        if (enemy.hp <= 0) {
          game.addScore(100);
          game.flash('#e67e22', 0.5);
          enemies = enemies.filter(e => e !== enemy);
        }
      }
    }
  }
}

function resetGame() {
  initUnits();
  initEnemies();
  turnCounter = 0;
}

function updateGame(dt) {
  updateUnits(dt);
  updateEnemies(dt);
  checkCollisions();
  if (game.input.pressed('Space')) {
    turnCounter++;
    game.addScore(50);
  }
  if (enemies.length === 0) {
    game.win({ message: 'All enemies defeated!' });
  }
}

function drawBackground(ctx) {
  ctx.fillStyle = game.palette[0];
  ctx.fillRect(0, 0, game.W, game.H);
  ctx.strokeStyle = game.palette[3];
  ctx.lineWidth = 0.5;
  for (let x = 0; x < game.W; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, game.H);
    ctx.stroke();
  }
  for (let y = 0; y < game.H; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(game.W, y);
    ctx.stroke();
  }
}

function drawGame(ctx) {
  drawBackground(ctx);
  drawGrid(ctx);
  drawUnits(ctx);
  drawEnemies(ctx);
  GF.Draw.vignette(ctx, game.W, game.H, 0.35);
}

game.add('play', {
  init() {
    resetGame();
  },
  reset() {
    resetGame();
  },
  update(dt) {
    updateGame(dt);
  },
  draw(ctx) {
    drawGame(ctx);
  }
});

game.titleScreen({
  subtitle: 'Defend the world one turn at a time!',
  onStart: () => game.go('play')
});
